hooks.command:
python3 -c "
import subprocess, json, sys
try:
    out = subprocess.check_output(['claude', 'mcp', 'list'], stderr=subprocess.DEVNULL, timeout=15, text=True)
except Exception:
    out = ''
not_connected = []
for name, label in [('kite', 'Kite (Zerodha)'), ('kotak-neo', 'Kotak Neo'), ('dhan', 'Dhan')]:
    line = next((l for l in out.splitlines() if l.strip().startswith(name + ':')), None)
    if not line or 'Connected' not in line:
        not_connected.append(label)
if not_connected:
    msg = 'TRADING MCP WARNING: ' + ', '.join(not_connected) + ' not connected.\nLogin before any trade analysis — see docs/broker-session-startup.md'
    print(json.dumps({'systemMessage': msg}))
"
